├── android/src/main/kotlin/com/example/core_<vendor>/
│   ├── Core<Vendor>Plugin.kt           ← Plugin 注册入口
│   └── <Vendor>Handler.kt             ← SDK 调用 + Channel 桥接
├── ios/Classes/
│   ├── Core<Vendor>Plugin.swift        ← Plugin 注册入口
